"""NUMBERS-MOVED.md from edits.E: per edit, before -> after text per draft, and every moved number -> where it lives -> SRC."""
from edits import E
o = ['# NUMBERS-MOVED — every number removed from the prose (PW-2 item 5), both drafts', '',
     'Generated by `pw2_draft_numbers/moved_md.py` from `edits.py` (the exact strings applied by `apply.py`). Every removed number also stays in the '
     '`.tex` as a `% PW2-5 moved -> <where>: <numbers>; SRC: <files>` comment beside the sentence it left (identical in both drafts). '
     'Rows marked ADDED are numbers that no float carried before; they were written into the named caption or table with a same-line `% SRC:`. '
     '"pointer comment" = no table or caption carries the number; it survives only as the `%` pointer (listed so the Head can decide).', '',
     '## Summary: where each moved number now lives', '', '| edit | section | numbers removed from the prose | now lives in | SRC |', '|---|---|---|---|---|']
for e in E:
    for nums, where, src in e['moved']:
        o.append('| %s | %s | %s | %s | `%s` |' % (e['id'], e['section'], nums.replace('|', '\\|'), where.replace('|', '\\|'), src))
o += ['', '## Every edit, before -> after (LaTeX source, comments included)', '']
for e in E:
    o.append('### %s — %s' % (e['id'], e['section']))
    for scope, old, new in e['pairs']:
        o += ['', '*%s*' % ('both drafts' if scope == 'both' else 'DRAFT-v2 only' if scope == 'v2' else 'DRAFT-v2-style only'), '',
              'before:', '```latex', old, '```', 'after:', '```latex', new, '```']
    o.append('')
print('\n'.join(o))
